# reconstruct partition mask and assign colors by component distance layers
H=W=30
wall=set()
for r in range(8): wall.add((r,6)); wall.add((r,21))
for c in range(7): wall.add((8,c))
for r in range(8,23): wall.add((r,21))
for c in range(14,22): wall.add((13,c))
for r in range(14,22): wall.add((r,14))
for c in range(30): wall.add((22,c))
# cell marker coordinates based on original task
marks={(6,4):1,(7,5):8,(14,15):1,(15,16):9,(19,11):1,(20,12):8,(21,13):6,(19,24):6,(20,23):5,(21,22):1,(23,20):7,(24,19):2,(25,18):6,(23,29):6,(24,28):5}
valid={(r,c) for r in range(H) for c in range(W) if (r,c) not in wall}
comps=[]
while valid:
    seed=valid.pop(); comp={seed}; stack=[seed]
    while stack:
        r,c=stack.pop()
        for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if p in valid:
                valid.remove(p); comp.add(p); stack.append(p)
    comps.append(comp)
[(len(x), sorted(marks[p] for p in x if p in marks)) for x in comps]

for r in range(23,30): wall.add((r,21))
valid={(r,c) for r in range(H) for c in range(W) if (r,c) not in wall}; comps=[]
while valid:
    seed=valid.pop(); comp={seed}; stack=[seed]
    while stack:
        r,c=stack.pop()
        for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if p in valid: valid.remove(p); comp.add(p); stack.append(p)
    comps.append(comp)
[(len(x), min(r for r,c in x), max(r for r,c in x),min(c for r,c in x),max(c for r,c in x), sorted(marks[p] for p in x if p in marks)) for x in comps]

# Final alternate: component-distance rings, with the region's original ground color as outermost layer.
out8=[[3 if (r,c) in wall else 4 for c in range(30)] for r in range(30)]
for comp in comps:
    mr=min(r for r,c in comp); mc=min(c for r,c in comp)
    if len(comp)==336: seq=[4,6,8,1]
    elif mr==14 and mc==15: seq=[1,9]
    elif mr==0 and mc==22: seq=[1,5,6]
    elif mr==23 and mc==0: seq=[7,2,6]
    elif mr==23 and mc==22: seq=[6,5]
    else: seq=[8,1]
    dist={}; from collections import deque
    q=deque()
    for r,c in comp:
        if any(p not in comp for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):dist[(r,c)]=1;q.append((r,c))
    while q:
        r,c=q.popleft()
        for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if p in comp and p not in dist:dist[p]=dist[(r,c)]+1;q.append(p)
    for (r,c),d in dist.items():out8[r][c]=seq[(d-1)%len(seq)]
print('\n'.join(' '.join(map(str,row)) for row in out8))
